scripts.qa-trace:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'qa-trace',
  description:
    'Navigate to a URL via run_playwright_script and capture an accessibility snapshot. Returns {loaded: boolean, snapshot: string, title: string}.',
  inputs: {
    url: { type: 'string', description: 'Target URL.', required: true },
    mode: {
      type: 'choice',
      description: 'What to do.',
      options: [{ value: 'smoke' }, { value: 'snapshot' }],
      default: 'smoke',
    },
  },
  outputs: {
    loaded: { type: 'boolean', description: 'True if the page loaded without a hard error.' },
    title: { type: 'string', description: 'Page title.', nullable: true },
    snapshot: { type: 'string', description: 'Truncated accessibility snapshot.' },
  },
  requires: ['network'],
});

async function main(): Promise<void> {
  const input = gezel.input as { url: string; mode?: string };
  const script = `
    import { chromium } from 'playwright';
    const browser = await chromium.launch();
    const ctx = await browser.newContext();
    const page = await ctx.newPage();
    let loaded = true;
    let title = '';
    try {
      const resp = await page.goto(${JSON.stringify(input.url)}, { waitUntil: 'domcontentloaded', timeout: 30_000 });
      if (resp && resp.status() >= 500) loaded = false;
      title = await page.title();
    } catch (err) {
      loaded = false;
    }
    const snap = await page.accessibility.snapshot({ interestingOnly: true }).catch(() => null);
    await browser.close();
    console.log(JSON.stringify({ loaded, title, snapshot: snap ? JSON.stringify(snap).slice(0, 16_000) : '' }));
  `;
  const raw = await gezel.mcp.call('run_playwright_script', { script });
  const text = typeof raw === 'string' ? raw : '';
  const jsonMatch = /\{[\s\S]*\}/.exec(text);
  if (!jsonMatch) {
    throw new Error(`run_playwright_script returned unparseable output: ${text.slice(0, 200)}`);
  }
  const parsed = JSON.parse(jsonMatch[0]!) as {
    loaded: boolean;
    title: string;
    snapshot: string;
  };
  gezel.log(`qa-trace ${input.url}: loaded=${parsed.loaded}, title="${parsed.title.slice(0, 80)}"`);
  gezel.output(parsed);
}

await main();
